const seen = new Set();   // click_ids we've already counted

function dedupAndCount(click) {
  // click: { clickId, adId, eventTs }
  if (seen.has(click.clickId)) return false;  // duplicate, skip
  seen.add(click.clickId);
  counts[click.adId] = (counts[click.adId] || 0) + 1;
  return true;  // counted
}
